import { CardNav } from "solen-design/react";

const items = [
  {
    label: "About",
    description: "The people and the story behind the studio.",
    links: [
      { label: "Company", href: "#" },
      { label: "Careers", href: "#" }
    ]
  },
  {
    label: "Projects",
    description: "Selected work from the last few years.",
    links: [
      { label: "Featured", href: "#" },
      { label: "Case studies", href: "#" }
    ]
  }
];

<CardNav
  items={items}
  logo="/logo.svg"
  logoAlt="Home"
  cta={{ label: "Get started", href: "#" }}
  theme="dark"
  surface="glass"
  openOn="click"
  cardEffect="rise"
  stagger={0.12}
  bounce={0.2}
  speed={1}
  cardHeight={176}
  maxWidth={800}
  accentColor="#f5c453"
  menuLabel={true}
  intro={true}
  onOpenChange={(open) => console.log(open)}
/>
